import math

def is_power_of_3(n):
    if n <= 0:
        return False
    return n > 0 and (n & (n - 1) == 0) and (n % 3 == 0 or n == 1) # Simplified check is better

def is_power_of_3_robust(n):
    if n <= 0:
        return False
    if n == 1:
        return True
    # Check if log3(n) is an integer
    if n > 0:
        return abs(math.log(n, 3) - round(math.log(n, 3))) < 1e-9
    return False

def solve_p3_test():
    p = 3
    max_val = 30

    # Numbers congruent to 2 mod 3 up to 30
    candidates = [i for i in range(1, max_val + 1) if i % 3 == 2]

    solutions = []

    print("--- Testing pairs (a, b) ---")

    for a in candidates:
        for b in candidates:
            if a > b:
                continue

            # Check conditions
            a_sq_plus_b = a**2 + b
            b_sq_plus_a = b**2 + a

            is_ax_power = is_power_of_3_robust(a_sq_plus_b)
            is_by_power = is_power_of_3_robust(b_sq_plus_a)

            if is_ax_power and is_by_power:
                solutions.append((a, b, a_sq_plus_b, b_sq_plus_a))
                print(f"Found solution: ({a}, {b}). Checks: {a}^2+b = {a_sq_plus_b} (3^x), b^2+a = {b_sq_plus_a} (3^y)")
            # else:
            #     print(f"Testing ({a}, {b}): Fail. a^2+b={a_sq_plus_b}, b^2+a={b_sq_plus_a}")

    if not solutions:
        print("\nNo solutions found in the tested range.")
    else:
        print("\nSolutions found:")
        for sol in solutions:
            print(sol)

solve_p3_test()
